import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with exact-fit bonus and a penalty for unusably small leftover gaps."""
    bins = np.asarray(bins, dtype=float)
    cap = float(np.max(bins))
    if cap <= 0:
        return np.zeros_like(bins)
    gap = bins - item                 # leftover space if item goes into this bin
    g = gap / cap                     # normalised leftover
    score = -g                        # best fit baseline (tighter is better)
    score = score + 2.0 * (g <= 1e-12)        # strong bonus for perfect fit
    score = score - 0.5 * ((g > 1e-12) & (g < 0.02))  # avoid tiny unusable slivers
    return np.nan_to_num(score, nan=0.0, posinf=0.0, neginf=-1e9)

import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a bonus for near-perfect fits.

    Leftover is normalised by bin capacity (the largest remaining capacity,
    since an empty bin is always present). Tight fits are preferred as in
    Best Fit, and leftovers near zero get an extra exponential bonus.
    """
    cap = float(np.max(bins))
    if cap <= 0.0:
        return np.zeros_like(bins, dtype=float)
    r = (bins - item) / cap  # normalised leftover in [0, 1]
    return -r + 0.5 * np.exp(-r / 0.01)
